import java.io.*;import java.security.*;import java.util.*;import com.android.apksig.ApkSigner;import org.bouncycastle.jce.provider.BouncyCastleProvider;
public class SignApk {public static void main(String[]a)throws Exception {Security.addProvider(new BouncyCastleProvider());KeyStore k=KeyStore.getInstance("BKS","BC");try(InputStream in=new FileInputStream(a[0])){k.load(in,new char[0]);}String alias=k.aliases().nextElement();PrivateKey key=(PrivateKey)k.getKey(alias,"Morphe".toCharArray());java.security.cert.X509Certificate cert=(java.security.cert.X509Certificate)k.getCertificate(alias);ApkSigner.SignerConfig c=new ApkSigner.SignerConfig.Builder(alias,key,List.of(cert)).build();new ApkSigner.Builder(List.of(c)).setInputApk(new File(a[1])).setOutputApk(new File(a[2])).setMinSdkVersion(26).setV4SigningEnabled(false).build().sign();}}
